				int repeatIndex, int lookaheadIndex, int value, int ruleIndex = -1)
			{
				Kind        = kind;
				State       = state;
				Position    = position;
				CallIndex   = callIndex;
				AtomicIndex = atomicIndex;
				RepeatIndex = repeatIndex;
				LookaheadIndex = lookaheadIndex;
